<?php
require_once __DIR__ . '/../includes/db.php'; require_once __DIR__ . '/../includes/functions.php'; require_admin();
if ($_SERVER['REQUEST_METHOD'] === 'POST') { if (!verify_csrf()) { set_flash('error','La sesión expiró. Intentá nuevamente.'); } else { $id = filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT); try { if ($id && $_POST['action'] === 'delete') { supabase_request('DELETE', 'contact_messages?id=eq.' . $id, null, ['Prefer: return=minimal']); set_flash('success','Mensaje eliminado correctamente.'); } elseif ($id && $_POST['action'] === 'read') { supabase_request('PATCH', 'contact_messages?id=eq.' . $id, ['status'=>'read'], ['Prefer: return=minimal']); set_flash('success','Mensaje marcado como leído.'); } } catch(Throwable $e) { set_flash('error','No se pudo actualizar el mensaje.'); } } header('Location: messages.php'); exit; }
$page_title = 'Mensajes'; require_once __DIR__ . '/../includes/admin-header.php'; $flash=get_flash(); try { $messages=supabase_request('GET', 'contact_messages?select=*&order=created_at.desc')['data']; } catch(Throwable $e) { $messages=[]; $db_error=true; }
?><section class="dashboard-content"><?php if ($flash): ?><div class="alert <?= e($flash['type']) ?>"><?= e($flash['message']) ?></div><?php endif; ?><?php if (!empty($db_error)): ?><div class="alert error">No fue posible leer la base de datos.</div><?php endif; ?><div class="table-card"><div class="card-heading"><div><h2>Consultas de contacto</h2><p>Administrá los mensajes recibidos desde el formulario.</p></div><span class="count"><?= count($messages) ?> total</span></div><?php if ($messages): ?><div class="table-scroll"><table class="messages-table"><thead><tr><th>Contacto</th><th>Consulta</th><th>Recibido</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><?php foreach($messages as $item): ?><tr><td><strong><?= e($item['name']) ?></strong><small><?= e($item['company'] ?: 'Sin empresa') ?></small><a href="mailto:<?= e($item['email']) ?>"><?= e($item['email']) ?></a><a href="tel:<?= e($item['phone']) ?>"><?= e($item['phone']) ?></a></td><td><strong><?= e($item['service'] ?: 'Consulta general') ?></strong><p><?= e($item['message']) ?></p></td><td><?= date('d/m/Y',strtotime($item['created_at'])) ?><small><?= date('H:i',strtotime($item['created_at'])) ?></small></td><td><span class="status <?= e($item['status']) ?>"><?= $item['status']==='new'?'Nuevo':'Leído' ?></span></td><td><div class="table-actions"><?php if($item['status']==='new'): ?><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$item['id'] ?>"><input type="hidden" name="action" value="read"><button class="action read" title="Marcar como leído">✓</button></form><?php endif; ?><form method="post" onsubmit="return confirm('¿Eliminar este mensaje?');"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$item['id'] ?>"><input type="hidden" name="action" value="delete"><button class="action delete" title="Eliminar">×</button></form></div></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="empty-state">Todavía no hay mensajes de contacto.</div><?php endif; ?></div></section><?php require_once __DIR__ . '/../includes/admin-footer.php'; ?>
